import chokidar from "chokidar";
import { mkdtemp, writeFile, unlink } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { randomBytes } from "node:crypto";

const dir = await mkdtemp(join(tmpdir(), "chok-"));
const watcher = chokidar.watch([dir], { ignoreInitial: true });
const events = [];
watcher.on("all", (e, p) => events.push(`${e} ${p.split("/").pop()}`));
await new Promise((r) => watcher.on("ready", r));

for (const [label, holdMs] of [["fast (no await)", 0], ["slow (250ms await)", 250]]) {
  events.length = 0;
  const f = join(dir, `.docsfn.${randomBytes(8).toString("hex")}.mjs`);
  await writeFile(f, "export default {}\n");
  if (holdMs) await new Promise((r) => setTimeout(r, holdMs));
  await unlink(f);
  await new Promise((r) => setTimeout(r, 600));
  console.log(`${label}: ${events.length} event(s) -> ${JSON.stringify(events)}`);
}
await watcher.close();
EOF
